/** Visible BSP face panels are not original map brushes. Their closing faces
 * are artificial. When adjacent panels share those faces, Three.js draws two
 * coplanar textured quads, causing severe z-fighting (not a WAD/UV defect).
 * Keep ALL brush planes for .MAP/CSG, but suppress the duplicated INTERNAL cap
 * triangles in the editor/preview. Reproject the synthetic exposed caps using
 * axes tangent to their own surfaces, never the source BSP front-face axes.
 * Also upgrades .svprefab files generated by the earlier BSP extractor.
 */
import type {Brush,Vec3,Face} from './types';
import {transformedVertices} from './geometry';

const sub=(a:Vec3,b:Vec3):Vec3=>[a[0]-b[0],a[1]-b[1],a[2]-b[2]];
const dot=(a:Vec3,b:Vec3)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
const mul=(a:Vec3,k:number):Vec3=>[a[0]*k,a[1]*k,a[2]*k];
const norm=(a:Vec3):Vec3=>{const length=Math.hypot(...a);return length>.00001?mul(a,1/length):[0,0,0]};
const key=(v:Vec3)=>v.map(x=>Math.round(x*100)/100).join(',');
const rounded=(n:number)=>Math.round(n*100)/100;

type Cap={brushIndex:number;faceIndex:number;t0:number;t1:number;normal:Vec3;group:string};
/** This function only applies to `recovery.mode === 'surface-shell'` BSP
 * prefabs. Ordinary MAP brushes and hull-0/exact solids must never be changed.
 * It is intentionally idempotent, so an old prefab can be repaired on placement
 * without changing the original .svprefab file on disk. */
export function repairBspSurfacePanels(input:readonly Brush[]):Brush[]{
  const brushes=input.map(brush=>({...brush,faces:brush.faces.map(face=>({...face}))}));
  const groups=new Map<string,Cap[]>();
  for(const [bi,brush] of brushes.entries()){
    if(brush.faces.length<5)continue;
    const vertices=transformedVertices(brush);
    const front=brush.faces[0];
    // The HF1/HF2 panel shape is [front vertices][back vertices], one
    // backside and one quad cap for every original front polygon edge.
    const n=front.indices.length;
    if(n<3||vertices.length!==2*n||brush.faces.length!==n+2)continue;
    // The reverse polygon is a fabricated closure. HF1-HF3 used the front
    // texture on it, making the back of a door look like another real face.
    // Never hide or change the authoritative source front (index 0).
    const back=brush.faces[1];
    if(back.indices.length===n && back.indices.every(i=>i>=n&&i<2*n))
      back.bspPrefabGeneratedBack=true;
    for(let fi=2;fi<brush.faces.length;fi++){
      const face=brush.faces[fi];
      if(face.indices.length!==4)continue;
      const [f0,b0,b1,f1]=face.indices;
      if(f0<0||f0>=n||f1<0||f1>=n||b0!==f0+n||b1!==f1+n)continue;
      const from=vertices[f0],to=vertices[f1],behind=vertices[b0];
      const edge=sub(to,from),extrude=sub(behind,from);
      if(Math.hypot(...edge)<.01||Math.hypot(...extrude)<.1)continue;
      // These artificial sides are never drawn and compile with NULL.
      // Retain the HF3 cap UV normalization for old project compatibility;
      // it MUST NOT modify the original BSP front-face texture projection.
      const u=norm(edge),v=norm(extrude);
      face.uAxis=u;face.vAxis=v;face.uShift=-dot(from,u);face.vShift=-dot(from,v);
      face.uScale=1;face.vScale=1;face.rotation=0;
      face.bspPrefabGeneratedCap=true;
      // Match the INFINITE edge line (not just identical vertices) to handle
      // real BSP T-junctions where one cap abuts two shorter caps.
      let tangent=u;
      const directionSign=tangent.find(x=>Math.abs(x)>1e-5)??1;
      if(directionSign<0)tangent=mul(tangent,-1);
      const foot=sub(from,mul(tangent,dot(from,tangent)));
      const group=`${key(tangent)}|${key(foot)}|${key(extrude)}`;
      const a=dot(from,tangent),b=dot(to,tangent);
      // Cap facing: adjacent panels have opposite edge winding.
      const sideNormal=norm([
        edge[1]*extrude[2]-edge[2]*extrude[1],
        edge[2]*extrude[0]-edge[0]*extrude[2],
        edge[0]*extrude[1]-edge[1]*extrude[0]
      ]);
      const cap:Cap={brushIndex:bi,faceIndex:fi,t0:Math.min(a,b),t1:Math.max(a,b),normal:sideNormal,group};
      const list=groups.get(group)??[];list.push(cap);groups.set(group,list);
    }
  }
  // Hide ONLY caps fully covered by oppositely-facing caps from other
  // panels. We do not change topology or delete faces needed for CSG. A cap
  // with an exposed partial edge stays rendered (no accidental holes).
  for(const caps of groups.values()){
    if(caps.length<2)continue;
    for(const cap of caps){
      const intervals=caps.filter(other=>other.brushIndex!==cap.brushIndex&&dot(cap.normal,other.normal)<-.99&&
        other.t0<cap.t1-.005&&other.t1>cap.t0+.005)
        .map(other=>[Math.max(cap.t0,other.t0),Math.min(cap.t1,other.t1)] as const)
        .sort((a,b)=>a[0]-b[0]);
      let covered=cap.t0;
      for(const [start,end] of intervals){if(start>covered+.015)break;covered=Math.max(covered,end);if(covered>=cap.t1-.015)break}
      if(covered>=cap.t1-.015)brushes[cap.brushIndex].faces[cap.faceIndex].bspPrefabInternalCap=true;
    }
  }
  return brushes;
}

/** Discard repeated geometry, not distinct faces merely sharing a material.
 * BSP face IDs can refer to identical coplanar polygons after selection
 * expansion. The original IDs remain in prefab.faceIds for traceability. */
export function deduplicateBspSurfacePanels(brushes:readonly Brush[]):Brush[]{
  const seen=new Set<string>();
  return brushes.filter(brush=>{
    const front=brush.faces[0],verts=transformedVertices(brush);
    if(!front||front.indices.length<3)return true;
    const corners=front.indices.map(i=>verts[i]&&key(verts[i])).sort().join(';');
    const first=verts[front.indices[0]],second=verts[front.indices[1]],third=verts[front.indices[2]];
    const a=sub(second,first),b=sub(third,first);
    const facing=key(norm([a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]]));
    // Same 2D outline with opposite facing or different panel depth is NOT a
    // duplicate: those are legitimate front/back layers of an object.
    const back=brush.faces[1]?.indices.map(i=>verts[i]&&key(verts[i])).sort().join(';');
    const signature=[corners,back,facing,front.texture.toLowerCase(),
      front.uAxis&&key(front.uAxis),front.vAxis&&key(front.vAxis),
      rounded(front.uShift??0),rounded(front.vShift??0),rounded(front.uScale??1),rounded(front.vScale??1)].join('|');
    if(seen.has(signature))return false;
    seen.add(signature);return true;
  });
}
